const tenantsWithDueNotifications = `-- name: TenantsWithDueNotifications :many
SELECT t::uuid AS tenant_id FROM app_tenants_with_due_notifications($1, $2::uuid, $3) AS t
`

type TenantsWithDueNotificationsParams struct {
	Now         time.Time
	AfterTenant *uuid.UUID
	MaxTenants  int32
}

func (q *Queries) TenantsWithDueNotifications(ctx context.Context, arg TenantsWithDueNotificationsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, tenantsWithDueNotifications, arg.Now, arg.AfterTenant, arg.MaxTenants)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var tenant_id uuid.UUID
		if err := rows.Scan(&tenant_id); err != nil {
			return nil, err
		}
		items = append(items, tenant_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

