const updateNotification = `-- name: UpdateNotification :execrows
UPDATE notifications
   SET recipients = $1, status = $2, status_reason = $3, send_after = $4,
       attempts = $5, lease_until = $6, last_error = $7,
       message_id = $8, sent_at = $9, updated_at = $10
 WHERE tenant_id = $11 AND id = $12 AND attempts = $13
`

type UpdateNotificationParams struct {
	Recipients       []string
	Status           string
	StatusReason     *string
	SendAfter        time.Time
	Attempts         int32
	LeaseUntil       *time.Time
	LastError        *string
	MessageID        *string
	SentAt           *time.Time
	UpdatedAt        time.Time
	TenantID         uuid.UUID
	ID               uuid.UUID
	ExpectedAttempts int32
}

func (q *Queries) UpdateNotification(ctx context.Context, arg UpdateNotificationParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateNotification,
		arg.Recipients,
		arg.Status,
		arg.StatusReason,
		arg.SendAfter,
		arg.Attempts,
		arg.LeaseUntil,
		arg.LastError,
		arg.MessageID,
		arg.SentAt,
		arg.UpdatedAt,
		arg.TenantID,
		arg.ID,
		arg.ExpectedAttempts,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertNotificationTemplate = `-- name: UpsertNotificationTemplate :one
INSERT INTO notification_templates (tenant_id, template_key, subject, body, updated_by, created_at, updated_at, version)
VALUES ($1, $2, $3, $4, $5, $6, $6, 1)
ON CONFLICT (tenant_id, template_key) DO UPDATE
   SET subject = EXCLUDED.subject, body = EXCLUDED.body, updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at,
       version = notification_templates.version + 1
RETURNING tenant_id, template_key, subject, body, updated_by, created_at, updated_at, version
`

type UpsertNotificationTemplateParams struct {
	TenantID    uuid.UUID
	TemplateKey string
	Subject     string
	Body        string
	UpdatedBy   *uuid.UUID
	Now         time.Time
}

func (q *Queries) UpsertNotificationTemplate(ctx context.Context, arg UpsertNotificationTemplateParams) (NotificationTemplate, error) {
	row := q.db.QueryRow(ctx, upsertNotificationTemplate,
		arg.TenantID,
		arg.TemplateKey,
		arg.Subject,
		arg.Body,
		arg.UpdatedBy,
		arg.Now,
	)
	var i NotificationTemplate
	err := row.Scan(
		&i.TenantID,
		&i.TemplateKey,
		&i.Subject,
		&i.Body,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
	)
	return i, err
}
